### Implement Scalar UDF

Source: https://github.com/apache/datafusion/blob/main/docs/source/contributor-guide/howtos.md

Implement the ScalarUDFImpl trait for scalar user-defined functions. Use the make_udf_function!() and export_functions!() macros. Add functions to relevant modules and consider creating new Rust features for conditional compilation.

```rust
use datafusion::logical_expr::ScalarUDFImpl;
use datafusion::scalar::ScalarUDF

struct MyScalarUDF;

impl ScalarUDFImpl for MyScalarUDF {
    fn as_any(&self) -> &dyn std::any::Any {
        self
    }

    fn name(&self) -> &str {
        "my_scalar_udf"
    }

    fn signature(&self) -> datafusion::logical_expr::Signature {
        // Define the function signature here
        datafusion::logical_expr::Signature::uniform_and_variadic_call_route(
            datafusion::arrow::datatypes::DataType::Int64,
            vec![datafusion::arrow::datatypes::DataType::Int64],
            datafusion::logical_expr::Volatility::Immutable
        )
    }

    fn return_type(&self, _arg_types: &[datafusion::arrow::datatypes::DataType]) -> datafusion::error::Result<datafusion::arrow::datatypes::DataType> {
        Ok(datafusion::arrow::datatypes::DataType::Int64)
    }

    fn evaluate_args(&self, args: &[datafusion::arrow::array::ArrayRef]) -> datafusion::error::Result<datafusion::arrow::array::ArrayRef> {
        // Implement the function logic here
        Ok(std::sync::Arc::new(datafusion::arrow::array::Int64Array::from(vec![1, 2, 3])))
    }
}

fn my_scalar_udf() -> datafusion::logical_expr::ScalarUDF {
    datafusion::logical_expr::ScalarUDF::from(MyScalarUDF)
}
```

