/// use datafusion_expr::TypeSignature::UniformCallSet;
/// use datafusion_expr::ColumnarValue;
/// use datafusion_expr::ScalarUDF;
/// use arrow::datatypes::DataType;
/// 
/// fn add_one(args: &[ColumnarValue]) -> Result<ColumnarValue> {
///     match args[0].clone() {
///         ColumnarValue::Scalar(scalar) => Ok(ColumnarValue::Scalar(scalar.cast_to(&DataType::Int64)?)),
///         ColumnarValue::Array(array) => {
///             let mut scalar_vec = Vec::with_capacity(array.len());
///             for i in 0..array.len() {
///                 scalar_vec.push(array.as_ref().as_any().downcast_ref::<arrow::array::Int64Array>().unwrap().value(i));
///             }
///             let result_array = arrow::array::Int64Array::from(scalar_vec);
///             Ok(ColumnarValue::Array(Box::new(result_array)))
///         }
///         _ => unimplemented!(),
///     }
/// }
/// 
/// let add_one_udf: ScalarUDF = ScalarUDF::new(
///     "add_one",
///     &Signature::one_of_args(vec![DataType::Int64]),
///     |args| add_one(args),
