### Rust: Update matched rows in a Delta table

Source: https://github.com/delta-io/delta-rs/blob/main/docs/usage/merging-tables.md

This Rust example demonstrates how to perform a merge operation with `when_matched_update`. It involves setting up the Delta table, writing initial data, defining the source data, and then executing the merge with specified update logic for matched rows.

```rust
use deltalake::arrow::array::{Int32Array};
use deltalake::arrow::datatypes::{DataType as ArrowDataType, Field, Schema as ArrowSchema, SchemaBuilder};
use deltalake::arrow::record_batch::RecordBatch;
use deltalake::builder::DeltaTableBuilder;
use deltalake::client::DeltaClient
use deltalake::datafusion::datasource::file_format::FormatOptions;
use deltalake::datafusion::error::Result;
use deltalake::datafusion::prelude::SessionContext;
use deltalake::kernel::{DataType, PrimitiveType, StructField, StructType};
use deltalake::storage::StorageOptions;
use deltalake::{DeltaOps, SaveMode, Schema, SchemaField};
use std::sync::Arc;

// define target table
let delta_ops = DeltaOps::try_from_uri("tmp/some-table").await?;
let mut table = delta_ops
    .create()
    .with_table_name("some-table")
    .with_save_mode(SaveMode::Overwrite)
    .with_columns(
        StructType::new(vec![
            StructField::new(
                "x".to_string(),
                DataType::Primitive(PrimitiveType::Integer),
                true,
            ),
            StructField::new(
                "y".to_string(),
                DataType::Primitive(PrimitiveType::Integer),
                true,
            ),
        ])
        .fields()
        .cloned(),
    )
    .await?;

let schema = Arc::new(Schema::new(vec![ 
    Field::new("x", arrow::datatypes::DataType::Int32, true),
    Field::new("y", arrow::datatypes::DataType::Int32, true),
]));
let mut record_batch_writer = deltalake::writer::RecordBatchWriter::for_table(&mut table)?;
record_batch_writer
    .write(RecordBatch::try_new(
        schema.clone(),
        vec![
            Arc::new(Int32Array::from(vec![1, 2, 3])),
            Arc::new(Int32Array::from(vec![4, 5, 6])),
        ],
    )?)
    .await?;

record_batch_writer.flush_and_commit(&mut table).await?;

let ctx = SessionContext::new();
let source_data = ctx.read_batch(RecordBatch::try_new(
    schema,
    vec![
        Arc::new(Int32Array::from(vec![2, 3])),
        Arc::new(Int32Array::from(vec![5, 6])),
    ],
)?)?;

DeltaOps(table)
    .merge(source_data, "target.x = source.x")
    .with_source_alias("source")
    .with_target_alias("target")
    .when_matched_update(|update| 
        update
        .update("x", "source.x")
        .update("y", "source.y"))?    .await?;
```

